def compute(vars):
    try:
        higher_pricing = vars["v1"]
        operating_income_increase = vars["v2"]
        result = (higher_pricing / operating_income_increase) * 100
    except ZeroDivisionError:
        return None

    return {
        "value": result,
        "trace": {
            "higher_pricing": higher_pricing,
            "operating_income_increase": operating_income_increase,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
